import "server-only";
import { and, eq, gt } from "drizzle-orm";
import { db } from "../../../db/dbClient";
import { authSessionsTable, usersTable } from "../../../db/schemas";

// auth_sessions.token_hash holds the hash of the session's *refresh* token.
export const authSessionRepository = {
  /** The id is generated by the caller because it is already inside the refresh token. */
  async insert(values: {
    id: string;
    userId: string;
    refreshTokenHash: string;
    expiresAt: Date;
    userAgent: string | null;
  }): Promise<void> {
    const { refreshTokenHash, ...rest } = values;
    await db
      .insert(authSessionsTable)
      .values({ ...rest, tokenHash: refreshTokenHash });
  },

  /** Used on every request: is the access token's session still alive? */
  async findValidById(sessionId: string, now: Date) {
    const [row] = await db
      .select({ userId: usersTable.id, status: usersTable.status })
      .from(authSessionsTable)
      .innerJoin(usersTable, eq(usersTable.id, authSessionsTable.userId))
      .where(
        and(
          eq(authSessionsTable.id, sessionId),
          eq(authSessionsTable.isRevoked, false),
          gt(authSessionsTable.expiresAt, now),
        ),
      );
    return row ?? null;
  },

  async findValidByRefreshTokenHash(refreshTokenHash: string, now: Date) {
    const [row] = await db
      .select({
        sessionId: authSessionsTable.id,
        userId: usersTable.id,
        status: usersTable.status,
      })
      .from(authSessionsTable)
      .innerJoin(usersTable, eq(usersTable.id, authSessionsTable.userId))
      .where(
        and(
          eq(authSessionsTable.tokenHash, refreshTokenHash),
          eq(authSessionsTable.isRevoked, false),
          gt(authSessionsTable.expiresAt, now),
        ),
      );
    return row ?? null;
  },

  /**
   * Swaps the refresh token, but only if the old hash is still current. If two refreshes
   * race with the same token, only one wins (returns true); the other gets false.
   */
  async rotateRefreshToken(
    sessionId: string,
    oldRefreshTokenHash: string,
    next: { refreshTokenHash: string; expiresAt: Date },
  ): Promise<boolean> {
    const rows = await db
      .update(authSessionsTable)
      .set({ tokenHash: next.refreshTokenHash, expiresAt: next.expiresAt })
      .where(
        and(
          eq(authSessionsTable.id, sessionId),
          eq(authSessionsTable.tokenHash, oldRefreshTokenHash),
          eq(authSessionsTable.isRevoked, false),
        ),
      )
      .returning({ id: authSessionsTable.id });
    return rows.length === 1;
  },

  async deleteByRefreshTokenHash(refreshTokenHash: string): Promise<void> {
    await db
      .delete(authSessionsTable)
      .where(eq(authSessionsTable.tokenHash, refreshTokenHash));
  },
};
